using System;
using UnityEngine;

namespace LittleLeo;

[CreateAssetMenu(fileName = "Timer", menuName = "Data/Statistics/StatisticsData/Timer")]
public class TimerStatistics : StatisticsData
{
	[Serializable]
	public class Data
	{
		public float value;
	}

	public Data data;

	public override string GetValue()
	{
		if (IsHidden())
		{
			return "";
		}
		if (float.IsNaN(data.value))
		{
			data.value = 0f;
		}
		TimeSpan timeSpan = TimeSpan.FromSeconds(data.value);
		return $"{(int)timeSpan.TotalHours}h {timeSpan.Minutes}m {timeSpan.Seconds}s";
	}

	protected override void SerializeValue()
	{
		jsonValueSerialized = JsonUtility.ToJson(data);
	}

	protected override void DeserializeValue()
	{
		JsonUtility.FromJsonOverwrite(jsonValueSerialized, data);
	}

	public override void Clear()
	{
		data.value = 0f;
	}

	public void SetLowerValueAndSave(string characterName, float newValue)
	{
		SetLowerValueAndSaveDefault(characterName, newValue);
	}

	private void SetLowerValueAndSaveDefault(string characterName, float newValue)
	{
		LoadStatisticsData(characterName);
		if (data.value == 0f || data.value > newValue)
		{
			data.value = newValue;
			SaveStatisticsData(characterName);
		}
	}

	public void AddAndSave(string characterName, float addValue)
	{
		AddAndSaveDefault("", addValue);
		AddAndSaveDefault(characterName, addValue);
	}

	private void AddAndSaveDefault(string characterName, float addValue)
	{
		LoadStatisticsData(characterName);
		data.value += addValue;
		SaveStatisticsData(characterName);
	}

	public void SubtractAndSave(string characterName, float subtractValue)
	{
		LoadStatisticsData(characterName);
		data.value -= subtractValue;
		SaveStatisticsData(characterName);
	}
}
